for(let i=0;i<cars.length;i++){let c=cars[i];if(!paused)c.z+=dt*c.speed;if(c.z>2230)c.z=-2230;dummy.position.set(c.x,1,c.z);dummy.rotation.set(0,0,0);dummy.scale.set(2.6,1.1,5.3);dummy.updateMatrix();carBody.setMatrixAt(i,dummy.matrix);dummy.position.y=1.8;dummy.scale.set(2.3,.8,2.8);dummy.updateMatrix();carTop.setMatrixAt(i,dummy.matrix);}carBody.instanceMatrix.needsUpdate=carTop.instanceMatrix.needsUpdate=true;
